const views={};
const readingSteps=n=>`<nav class="learning-progress" aria-label="테스트 진행 단계">${stepper(['학습 준비','지문 읽기','문항 응답','제출 완료'],n)}</nav>`;
const markedSentences=[8,13];
function passageMarkup(interactive=false){if(!interactive&&st.assignment&&st.assignment.text!==passagePlain)return `<div class="passage">${st.assignment.text.split(/\n\s*\n/).map(p=>`<p>${esc(p)}</p>`).join('')}</div>`;let n=-1;return `<div class="passage">${paras.map(p=>`<p>${p.map(s=>{n++;return interactive?`<span role="button" tabindex="0" class="sentence ${markedSentences.includes(n)||st.comments.some(c=>c.quote===n)?'marked':''} ${st.quote===n?'chosen':''}" data-sentence="${n}" aria-label="근거 선택: ${esc(plainSentence(s))}" aria-pressed="${st.quote===n}">${richSentence(s)}</span>`:richSentence(s)}).join(' ')}</p>`).join('')}</div>`}
const articleMeta=()=>`<div class="article-meta"><span>고등학교 국어·화법</span><span>·</span><span>발표</span><span>·</span><span>26년 고1 3월 모의고사 (1~3) 지문</span></div>`;
const memberAvatars=()=>`<div class="avatar-stack">${Object.entries(st.committedGroups??st.groups).filter(([,g])=>g===(st.committedGroups??st.groups).김서윤).map(([n],i)=>av(n,i%2?'mint':'lavender')).join('')}<small>우리 모둠</small></div>`;
const groupName=()=>(st.committedGroups??st.groups).김서윤===0?'논리 엮기 그룹':'관점 탐색 모둠';
function testItem(title,state,desc,to,action){return `<article class="list-item"><div class="tag-icon">${icon('book')}</div><div class="list-copy">${badge(state,state.includes('완료')?'green':'')}<h3>${title}</h3><p>${desc}</p></div>${action?button('제출 내용 보기',action,'secondary sm'):link(state==='제출 완료'?'결과 안내':'테스트 시작 '+icon('arrow'),to,'btn soft sm')}</article>`}
// Home assignment metadata only; the reading/questions still use the original demo fixture.
const studentHomeAssignment={dateLabel:'11월 14일 지문',title:'호작도 속 호랑이와 까치의 의미',description:'호랑이와 까치에 담긴 옛사람들의 생각을 읽어보세요.',sourceLabel:'26년 고1 3월 모의고사 (1~3) 지문',sourceUrl:'https://wdown.ebsi.co.kr/W61001/01exam/20260324/go1/kor_main_mun_25R6W2G6_1.pdf',titleIsEditorial:true};
function homeBookArt(){return `<svg class="home-book-art" viewBox="0 0 180 170" aria-hidden="true"><path d="M25 87C15 43 53 18 100 28s72 35 60 75-50 49-89 38S33 123 25 87Z" fill="#d5e7f3" opacity=".55"/><path d="M33 64c19-7 37-4 57 9 20-13 38-16 57-9v67c-21-6-40-2-57 8-17-10-36-14-57-8Z" fill="#f9fcff" stroke="#a9c7da" stroke-width="2" stroke-linejoin="round"/><path d="M90 74v64M44 79c12-2 23 0 34 6M44 92c12-2 23 0 34 6M44 105c12-2 23 0 34 6M102 85c11-6 22-8 33-6M102 98c11-6 22-8 33-6M102 111c11-6 22-8 33-6" stroke="#bfd6e6" stroke-width="2" stroke-linecap="round" fill="none"/><path d="M143 32v12m-6-6h12M39 40v8m-4-4h8" stroke="#a5c7dd" stroke-width="2" stroke-linecap="round"/><circle cx="149" cy="140" r="4" fill="#bcd6e8"/></svg>`}
views['s-home']=()=>`<div class="student-home-screen">${head('서윤님, 오늘의 읽기를 시작해요.','오늘의 지문과 이전 피드백을 확인해 보세요.',badge('인하고등학교 · 1학년 2반','gray'))}<div class="grid-main student-home-grid"><div class="stack home-primary"><section class="welcome-hero">${homeBookArt()}${badge(studentHomeAssignment.dateLabel,'white')}<h2>${esc(st.assigned?st.assignment.title:studentHomeAssignment.title)}</h2><p>${esc(studentHomeAssignment.description)}</p><div class="home-meta"><span>${studentHomeAssignment.sourceLabel}</span><span>지문 1개 · 문항 3개</span></div><div class="actions">${st.submitted?link('제출 완료 안내 '+icon('check'),'s-complete','btn secondary'):link('배정 테스트 시작 '+icon('arrow'),'s-prep','btn')}</div></section><section class="card home-feedback"><div class="section-head"><h2>이전 테스트 피드백</h2></div><p class="home-feedback-source">김하늘 선생님 · 도시의 녹지는 누구를 위한 것인가</p><div class="home-feedback-summary"><svg viewBox="0 0 44 40" aria-hidden="true"><path d="M8 12h26M8 20h18m0 0-5-5m5 5-5 5M8 30h26" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg><p>근거 문장에서 시선이 되돌아갔어요. 핵심어를 표시하며 앞뒤 내용을 연결해 보세요.</p></div>${link('피드백과 추천 학습 확인 '+icon('arrow'),'s-feedback')}</section></div><aside class="stack home-rail"><section class="card home-flow"><span class="eyebrow">TODAY’S FLOW</span><h3>오늘의 학습 흐름</h3><ol class="focus-list"><li><i>1</i>오늘의 지문을 읽고 테스트해요.</li><li><i>2</i>지난 피드백에서 읽기 전략을 찾아요.</li><li><i>3</i>추천 학습으로 한 번 더 연습해요.</li></ol></section><section class="card home-tip"><div class="ai-label">${icon('spark')} 오늘의 읽기 전략</div><h3>상징과 의미를 연결해요.</h3><p class="small">호랑이와 까치가 무엇을 뜻하는지, 설명하는 문장과 함께 읽어보세요.</p></section></aside></div></div>`;
views['s-tests']=()=>`<div class="student-tests-screen">${head('나의 테스트','오늘의 테스트와 지난 제출 기록을 확인하세요.')}<div class="test-list-cards"><section class="card test-list-card"><div class="section-head"><h2>오늘의 테스트</h2><span class="test-card-date">11월 14일</span></div>${testItem(studentHomeAssignment.title,st.submitted?'제출 완료':'미제출','3회차 · 지문 1개 · 문항 3개','s-prep',st.submitted?'view-submission':null)}</section><section class="card test-list-card"><div class="section-head"><h2>지난 테스트</h2></div>${testItem('도시의 녹지는 누구를 위한 것인가','제출 완료','2회차 · 11월 11일 · 피드백 게시됨','s-feedback','past-city-test')}</section></div><div style="margin-top:20px">${note('배정 테스트에서는 정답과 힌트를 제공하지 않아요. 추가 학습에서는 별도로 힌트와 해설을 확인할 수 있어요.')}</div></div>`;
views['s-prep']=()=>`<div class="learning-screen student-prep-screen prep-flow"><h1 class="sr-only">학습 준비</h1>${readingSteps(0)}<section class="card prep-stage-card">${st.prep===0?`<header class="prep-card-header"><h2>01 · 카메라·환경 점검</h2><p>얼굴이 정면으로 보이고, 눈이 가려지지 않는 환경을 준비해 주세요.</p></header><div class="prep-columns"><div class="prep-surface prep-camera-surface"><div class="prep-camera-guide"><div class="face-outline"></div></div><span class="prep-surface-caption">카메라 영상 대신 표시하는 안내 화면</span></div><div class="prep-side-panel"><div class="prep-tip"><h3>밝은 환경</h3><p>강한 역광을 피하고 얼굴이 잘 보이게 해요.</p></div><div class="prep-tip"><h3>안정적인 자세</h3><p>화면과 적당한 거리를 유지해요.</p></div><div class="prep-actions">${button('카메라·환경 점검하기 '+icon('check'),'prep-check')}${button('점검 실패 안내 보기','prep-error','secondary')}</div></div></div>`:st.prep===1?`<header class="prep-card-header"><div class="prep-title-row"><h2>02 · 시선 보정</h2><span class="calibration-step-status" role="status">보정 지점 ${st.cal+1} / 5</span></div><p>화면의 점을 눈으로 따라봐주세요.</p></header><div class="prep-columns">${calibrationSurface()}<div class="prep-side-panel calibration-side"><div class="prep-tip"><h3>점을 따라 시선을 옮겨요.</h3><p>점이 멈추면 다음 지점으로 이동하세요.<br>머리를 편안하게 고정해 주세요.</p></div><div class="prep-actions">${button(st.cal===4?'보정 완료 상태 확인':'다음 지점 '+icon('arrow'),'cal-next')}${button('다시 시작','cal-reset','secondary')}</div></div></div>`:`<div class="prep-completed"><div class="complete-icon">${icon('check')}</div><h2>준비가 완료되었어요.</h2><p>지문을 읽고 문항에 응답해 주세요.</p>${link('지문 읽기 시작 '+icon('arrow'),'s-reading','btn')}</div>`}</section></div>`;
views['s-reading']=()=>`<div class="learning-screen">${readingSteps(1)}<article class="reader learning-main-card reading-stage-card"><div class="reader-toolbar"><div class="label-line">${badge('당일 지문')}<span class="micro">1 / ${st.compare?2:1}</span></div><div class="reader-tools"><div class="font-tool"><button data-action="font-minus" aria-label="글자 작게">가−</button><span>${st.font}px</span><button data-action="font-plus" aria-label="글자 크게">가+</button></div>${link('테스트 안내','s-prep')}</div></div><div class="article reading-content"><span class="eyebrow">READ & UNDERSTAND</span><h1>${esc(st.assignment?.title??passageTitle)}</h1>${articleMeta()}${passageMarkup()}${st.assignment?.compare?`<div class="divider"></div><span class="eyebrow">COMPARATIVE READING</span><h1 style="font-size:25px">공공 도서관의 문턱</h1><div class="passage"><p>도서관의 수가 늘어나는 것과 시민이 도서관을 편하게 이용하는 것은 같은 일이 아니다. 운영 시간, 교통편, 자료의 언어와 접근 가능한 시설이 갖추어져야 이용의 기회가 넓어진다.</p><p>공공 시설의 가치는 시설의 양에 더해 누구의 삶과 연결되는지를 함께 살필 때 드러난다.</p></div>`:''}</div><div class="reader-bottom"><p class="small">속도보다 이해가 중요해요.<br>지문은 문항 응답 중에도 다시 볼 수 있어요.</p>${button('읽기 완료 · 문항으로 '+icon('arrow'),'read-done')}</div></article></div>`;
const questions=[{type:'선택형',domain:'핵심 내용 파악',text:'발표에서 설명한 호작도 속 호랑이와 까치의 의미로 가장 적절한 것은?',choices:['호랑이는 끝까지 두려운 존재로만 그려졌고, 까치는 나쁜 소식을 알리는 새로 여겨졌다.','호랑이는 나쁜 기운을 막아 주는 친근한 수호자로, 까치는 기쁜 소식을 전하는 길조로 그려졌다.','호랑이는 의연하고 듬직한 모습으로 그려져 권위를 상징했고, 까치는 호랑이를 경계하는 새였다.','호랑이와 까치는 최근 케이팝 애니메이션에서 처음 만들어진 상징이다.']},{type:'서술형',domain:'맥락 파악·추론',text:'사람들이 두려운 존재였던 호랑이를 호작도에 익살스럽게 그린 까닭을 발표 내용과 연결해 설명하세요.'},{type:'서술형',domain:'비판적 읽기',text:'발표자가 청중의 이해를 돕기 위해 사용한 말하기 방법 두 가지를 찾아, 각각 어떤 효과가 있는지 설명하세요.'}];
views['s-answer']=()=>`<div class="learning-screen">${readingSteps(2)}<section class="card learning-main-card answer-stage-card"><header class="answer-stage-header"><div class="answer-stage-topline"><div><h1>문항에 응답해 주세요.</h1><p>답안을 확인한 뒤 최종 제출하세요.</p></div>${button('지문 다시 보기','show-passage','secondary')}</div><div class="question-tabs">${questions.map((q,i)=>`<button data-q="${i}" class="question-tab ${st.q===i?'active':''} ${st.answers[i].trim()?'answered':''}">문항 ${i+1} · ${q.type}</button>`).join('')}</div></header><div class="answer-content"><div class="label-line">${badge(questions[st.q].type)}${badge(questions[st.q].domain,'gray')}</div><h2 class="question-title">${st.q+1}. ${questions[st.q].text}</h2>${st.q===0?questions[0].choices.map((c,i)=>`<label class="choice"><input type="radio" name="mc-answer" value="${i}" ${st.answers[0]===String(i)?'checked':''}><span>${i+1}. ${c}</span></label>`).join(''):`<div class="filter-row question-mode"><div class="segments" aria-label="답안 입력 방식"><button data-mode="typing" class="${st.mode==='typing'?'active':''}" aria-pressed="${st.mode==='typing'}">텍스트 입력</button><button data-mode="hand" class="${st.mode==='hand'?'active':''}" aria-pressed="${st.mode==='hand'}">필기·OCR 확인</button></div></div>${st.mode==='typing'?`<label class="sr-only" for="answer-text">문항 ${st.q+1} 답안</label><textarea id="answer-text" data-answer="${st.q}" class="answer-editor" placeholder="글에서 찾은 근거와 자신의 설명을 함께 적어주세요.">${esc(st.answers[st.q])}</textarea>`:`<p class="small" style="margin-bottom:14px">마우스·펜·손가락으로 답안을 적어보세요.</p><canvas class="handwriting" id="ink" aria-label="필기 답안 입력 영역"></canvas><div class="canvas-toolbar"><span class="micro">필기 입력 가능</span><button class="link-btn" data-action="ink-clear">필기 지우기</button></div>${button('OCR로 변환','ocr-example','soft')}${st.ocr?`<div class="ocr-box"><h3>인식 텍스트 확인</h3><p class="small">변환한 문장을 확인하고, 필요하면 고친 뒤 답안에 적용하세요.</p><label class="sr-only" for="ocr-text">OCR 인식문 확인·수정</label><textarea id="ocr-text" data-bind="ocr">${esc(st.ocr)}</textarea><label class="check-row"><input type="checkbox" id="ocr-confirm" ${st.ocrConfirmed?'checked':''}><span>변환 텍스트를 확인하고 필요한 부분을 수정했어요.</span></label>${button('확인한 텍스트를 답안에 적용','ocr-apply','secondary')}</div>`:''}${st.answers[st.q]?note('현재 답안: '+esc(st.answers[st.q])):''}`}`}</div><div class="answer-foot"><span class="small">${st.answers.filter(x=>x.trim()).length} / 3문항 작성</span><div class="actions">${st.q>0?button('이전 문항','q-prev','secondary'):''}${st.q<2?button('다음 문항 '+icon('arrow'),'q-next'):button('답안 확인·제출','review-submit')}</div></div></section></div>`;
views['s-complete']=()=>`<div class="learning-screen">${readingSteps(3)}<section class="card learning-main-card test-complete-card"><div class="complete-icon">${icon('check')}</div><h1>${st.submitted?'응답 내용이 저장되었어요':'제출 결과를 확인해 주세요.'}</h1><div class="actions">${st.submitted?button('내 제출 답안 보기','view-submission','secondary'):link('나의 테스트','s-tests','btn secondary')}${link('학생 홈으로','s-home','btn')}</div><p class="small">수업 후 선생님이 검토·게시한 피드백을 확인하세요.</p></section></div>`;
views['s-feedback']=()=>renderStudentFeedbackPage();
function talkContent(){const initial=[{name:'이지우',text:'호랑이는 원래 무서운 존재였지만, 그 힘이 나쁜 기운을 막아 준다고 믿어서 수호자가 된 것 같아요.',quote:8},{name:'박하린',text:'눈을 크게, 발을 뭉툭하게 그린 건 무섭지 않게 곁에 두고 싶었던 마음 때문이라는 부분이 인상적이에요.',quote:13}];return `<div class="discussion-body"><div class="ai-prompt"><div class="ai-label">${icon('spark')} AI 추가 질문</div><p>${['호랑이가 공포의 대상에서 수호자로 받아들여진 까닭을 발표 속 근거와 함께 설명해 보세요.','호랑이를 익살스럽게 그린 것과 까치를 그려 넣은 것에는 각각 어떤 바람이 담겼을까요?','발표자가 자료를 가리키거나 청중에게 질문한 방법은 이해에 어떤 도움을 주었나요?'][st.aiQuestion]}</p><button class="link-btn" style="font-size:12px;margin-top:9px" data-action="ai-question">다른 질문 살펴보기</button></div>${[...initial,...st.comments].map(c=>`<div class="comment">${av(c.name,c.name==='김서윤'?'':'mint')}<div class="comment-content"><div class="comment-head"><strong>${c.name}</strong><span>${c.name==='김서윤'?'나의 의견':'모둠원'}</span></div><p>${esc(c.text)}</p>${c.quote!==null?`<div class="quote">${esc(sentences[c.quote])}</div>`:''}</div></div>`).join('')}</div><form id="comment-form" class="comment-form">${st.quote!==null?`<div class="selected-quote"><span>선택한 근거: ${esc(sentences[st.quote])}</span><button type="button" data-action="quote-clear" aria-label="근거 첨부 해제">×</button></div>`:''}<label class="sr-only" for="comment-text">근거와 함께 남길 의견</label><textarea id="comment-text" placeholder="내 생각과 그 근거를 함께 적어보세요." maxlength="1500" required></textarea><div class="actions"><span class="micro"></span><button type="submit" class="btn sm">의견 남기기 ${icon('send')}</button></div></form>`}
function groupSummary(){return `<div class="discussion-body"><h3>우리 모둠의 공동 설명·요약</h3><p class="small" style="margin:12px 0 18px">${esc(st.groupTask)}</p><label class="sr-only" for="summary-text">공동 결과물 작성</label><textarea id="summary-text" class="summary-editor" data-bind="summary" ${st.groupSubmitted?'readonly':''} placeholder="함께 찾은 근거를 연결해, 우리 모둠의 설명을 완성하세요.">${esc(st.summary)}</textarea><p class="version-info" style="margin:12px 0">${st.groupSubmitted?'제출본':'작성 중'}</p><div class="actions">${st.groupSubmitted?button('다시 수정','group-reopen','secondary'):button('공동 결과물 제출','group-submit')}</div>${st.teacherGroupFeedback?`<div class="divider"></div><h3>선생님의 모둠 피드백</h3><p class="feedback-snippet">${esc(st.teacherGroupFeedback)}</p>`:''}</div>`}
views['s-group']=()=>`${head(groupName(),'공동 지문에서 근거를 찾고, 서로의 생각을 연결해요.',memberAvatars())}<section class="card" style="margin-bottom:23px"><div class="spread"><div><span class="eyebrow">OUR GOAL</span><h3 style="margin:9px 0">${esc(st.groupGoal)}</h3><p class="small">${esc(st.groupTask)}</p></div>${badge(st.groupSubmitted?'제출 완료':'활동 중',st.groupSubmitted?'green':'')}</div></section><div class="collab-layout"><article class="reader"><div class="reader-toolbar"><h3>공동 지문</h3>${badge('당일 지문','gray')}</div><div class="selection-instruction">${icon('edit')}문장을 선택해 의견에 근거로 첨부하세요.</div><div class="article"><span class="eyebrow">READ TOGETHER</span><h1>${passageTitle}</h1>${articleMeta()}${passageMarkup(true)}</div></article><section class="card discussion">${tabs([['talk','주석·토론 '+(2+st.comments.length)],['summary','공동 결과물']],st.tab,'group')}<div role="tabpanel">${st.tab==='talk'?talkContent():groupSummary()}</div></section></div>`;
views['s-history']=()=>`${head('나의 학습 기록','테스트, 지난 피드백, 모둠 결과물을 이어서 살펴보세요.')}<section class="card"><div class="timeline">${st.submitted?`<article class="timeline-item"><div class="timeline-date">오늘</div><div class="timeline-body">${badge('테스트 제출','green')}<h3>${passageTitle}</h3><p>3회차 · 답안 3개 · 시선 데이터 미수집</p>${button('제출 답안 보기','view-submission','secondary sm')}</div></article>`:''}${st.optionalDone?`<article class="timeline-item"><div class="timeline-date">오늘</div><div class="timeline-body">${badge('추가 학습','green')}<h3>${st.optionalResource===1?'숫자는 무엇을 설명하는가':'공공 도서관의 문턱'}</h3><p>선택형 추가 학습 · 해설 확인</p></div></article>`:''}${st.groupSubmitted?`<article class="timeline-item"><div class="timeline-date">오늘</div><div class="timeline-body">${badge('모둠 제출','green')}<h3>${groupName()}의 공동 결과물</h3>${link('공동 결과물 보기','s-group')}</div></article>`:''}<article class="timeline-item"><div class="timeline-date">11.11<br>2회차</div><div class="timeline-body">${badge('교사 피드백','gray')}<h3>정보의 신뢰성을 판단하는 기준</h3><p>게시된 피드백과 추천 학습을 다시 확인하세요.</p>${button('지난 피드백 보기','past-test','secondary sm')}</div></article><article class="timeline-item"><div class="timeline-date">11.06<br>1회차</div><div class="timeline-body">${badge('모둠 활동','gray')}<h3>서로 다른 근거를 비교하며 읽기</h3><p>근거를 비교하는 공동 설명문 작성</p>${button('지난 활동 보기','past-group','secondary sm')}</div></article></div></section>`;
function settings(teacher){return `${head('설정','계정·기기 환경과 데이터 관리 안내를 확인하세요.')}<div class="grid-main"><section class="card"><div class="setting-row"><div><h3>내 계정·담당 학급</h3><p>${teacher?'김하늘 선생님':'김서윤 학생'} · 인하고등학교 ${st.className}</p></div>${badge(teacher?'교사':'학생','gray')}</div>${teacher?'':`<div class="setting-row"><div><h3>페이스패스 등록 상태</h3><p>등록 완료 · 얼굴 사진 대신 특징값만 이 기기에 저장해요.<br>도움이 필요하면 담당 선생님에게 문의하세요.</p></div>${button('화면 안내','face-help','secondary sm')}</div>`}<div class="setting-row"><div><h3>지문 글자 크기</h3><p>기본 20px · 화면에서 편안한 크기로 조정하세요.</p></div><label><span class="sr-only">지문 글자 크기 선택</span><select id="font-select">${[18,20,22,24].map(n=>`<option value="${n}" ${st.font===n?'selected':''}>${n}px</option>`).join('')}</select></label></div><div class="setting-row"><div><h3>기기 환경</h3><p>노트북·태블릿 화면 대응<br>화면 크기나 앉은 자세가 바뀌면 시선 보정을 다시 해 주세요.</p></div>${icon('camera')}</div><div class="setting-row"><div><h3>로그아웃</h3><p>다른 계정으로 들어가려면 로그아웃 후 다시 로그인하세요.</p></div>${button('로그아웃','logout','secondary sm')}</div></section><aside class="stack"><section class="card"><h3>데이터 보관·삭제 안내</h3><p class="small" style="margin-top:14px">학습 기록은 이 기기의 브라우저에 저장되고, 삭제하기 전까지 남아 있어요. 카메라 영상은 저장하지 않아요.</p></section></aside></div>`}
views['s-settings']=()=>settings(false);views['t-settings']=()=>settings(true);
